9	/**
10	 * Rejects a create-owner request whose city already holds {@link #CAPACITY} or more owners.
11	 * The request's city is compared with each stored owner's city case-insensitively, with
12	 * surrounding whitespace trimmed, so "Sydney" and " sydney " count towards the same city.
13	 * Runs before {@link BuildOwner} (it reads the request DTO, not the built entity) and before
14	 * {@link SaveOwner} (so the request itself is not counted). On reaching the cap raises
15	 * {@link CityAtCapacityException} (409).
16	 */
17	public class CheckOwnerCityCapacity {
18	
19	    /** Maximum number of owners permitted per city; the request is rejected at this count. */
20	    public static final int CAPACITY = 50;
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws CityAtCapacityException {
24	        String city = normalize(request.getCity());
25	        int count = 0;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (city.equals(normalize(existing.getCity()))) {
28	                count++;
29	            }
30	        }
31	        if (count >= CAPACITY) {
32	            throw new CityAtCapacityException(request.getCity(), count);
33	        }
34	    }
35	
36	    /** Lower-case and trim, treating null as empty, for case-insensitive city comparison. */
37	    private static String normalize(String value) {
38	        return value == null ? "" : value.trim().toLowerCase();
39	    }
40	}
