1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Raised when a create-owner request names a city that already holds the maximum number of
5	 * owners ({@link org.springframework.samples.petclinic.rest.function.owner.CheckOwnerCityCapacity#CAPACITY}
6	 * or more), compared case-insensitively with surrounding whitespace trimmed. Carries the
7	 * requested city and the current count so the handler can report why the city is full.
8	 */
9	public class CityAtCapacityException extends Exception {
10	
11	    private final String city;
12	
13	    private final int count;
14	
15	    public CityAtCapacityException(String city, int count) {
16	        super("City '" + city + "' already has " + count + " owners and is at capacity");
17	        this.city = city;
18	        this.count = count;
19	    }
20	
21	    public String getCity() {
22	        return city;
23	    }
24	
25	    public int getCount() {
26	        return count;
27	    }
28	}
