8	
9	/**
10	 * Turns a {@link CityAtCapacityException} into a 409 naming {@code city} in the body's
11	 * {@code errors} array, mirroring the shape of the other owner-field responses.
12	 */
13	public class CityAtCapacityHandler {
14	
15	    public void handle(@Parameter CityAtCapacityException ex,
16	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
17	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT,
18	                "City is at capacity");
19	        detail.setProperty("errors", java.util.List.of("city"));
20	        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
21	    }
22	}
