1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Derives the read-time {@code bulkSignupWarning} flag on an owner: {@code true} once more than
11	 * {@link #BULK_THRESHOLD} owners have already been registered on the current business day
12	 * (server date rolled forward off any weekend, matching {@link BusinessDay}), otherwise
13	 * {@code false}. Runs before the responder so the flag is carried onto the returned DTO.
14	 */
15	public class MarkBulkSignupWarning {
16	
17	    /** The warning is raised once the count of owners created today exceeds this value. */
18	    public static final int BULK_THRESHOLD = 80;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        LocalDate today = BusinessDay.rollForward(LocalDate.now());
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (today.equals(existing.getRegistrationDate())) {
25	                count++;
26	            }
27	        }
28	        owner.setBulkSignupWarning(count > BULK_THRESHOLD);
29	    }
30	}
